select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"open_library_id":"OL2660296A"},"seq":1,"relation":"authors","after_row":{"id":987332001,"name":"Marquis de Sade","open_library_id":"OL2660296A"},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL962240W"},"seq":2,"relation":"works","after_row":{"id":987132001,"title":"Justine","cover_id":6454588,"author_id":987332001,"work_type":"novel","source_type":"open_library","open_library_id":"OL962240W","first_publish_year":1791,"native_identity_key":"nlscale:20261102:ol:OL962240W"},"before_row":null},{"key":{"open_library_edition_id":"OL24328801M"},"seq":3,"relation":"editions","after_row":{"id":987232001,"title":"Justine, of De tegenspoed der deugdzaamheid","isbn_10":null,"isbn_13":"9789060195529","work_id":987132001,"cover_id":6454588,"language":"dut","publisher":"Bert Bakker","publish_date":null,"open_library_edition_id":"OL24328801M"},"before_row":null},{"key":{"work_id":987132001,"language":"nl"},"seq":4,"relation":"catalog_work_descriptions","after_row":{"text":"Na de dood van haar ouders moet Justine zonder middelen haar weg vinden. Ze probeert vast te houden aan haar overtuiging dat een deugdzaam leven de juiste keuze is, maar ontmoet telkens mensen die haar afhankelijkheid misbruiken. Haar ervaringen zetten die overtuiging steeds verder onder druk. De roman verbindt haar omzwervingen met scherpe aanvallen op maatschappelijke instellingen en ideeën over goed en kwaad. Het contrast tussen haar bedoelingen en haar behandeling door anderen vormt de kern van het verhaal.","work_id":987132001,"evidence":[{"note":"Exact Dutch paperback9789060195529/KBp801595169,p802527558,p802539505 translates1791Justine, not1787conte or1797NouvelleJustine. Oxford scholarly introduction independently distinguishes versions. GemmaPappot is translator, not coauthor; sourcepublisher/userhandle not personcredits. Reprinting1967/1983 differs from originalpublication1791; no false exactprintingdate imported. Nongraphic original premise only.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p801595169","https://data.bibliotheken.nl/id/nbt/p802527558","https://data.bibliotheken.nl/id/nbt/p802539505"],"reference":"new-work-dossier-readings-033.json#94","checked_at":"2026-11-03T06:56:27.665Z"},{"type":"original_substantive_source_review","review":"content-amendment-014.json","sources":["https://api.pageplace.de/preview/DT0400.9780191635755_A23590458/preview-9780191635755_A23590458.pdf","https://www.deslegte.com/justine-of-de-tegenspoed-der-deugdzaamheid-123150/","https://www.bol.com/nl/nl/p/justine-of-de-tegenspoed-der-deugdzaamheid-de-sade/1001004005122825/","https://openlibrary.org/works/OL962240W","https://data.bibliotheken.nl/id/nbt/p801595169","https://data.bibliotheken.nl/id/nbt/p802527558","https://data.bibliotheken.nl/id/nbt/p802539505"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"27e2c6c2a51a3694e2c41ab09b96a889b7f9354d49c5d24f21b27cc5b3bfc770","cover_id":6454588,"reference":"cover-semantic-review-013.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://api.pageplace.de/preview/DT0400.9780191635755_A23590458/preview-9780191635755_A23590458.pdf","reviewed_at":"2026-11-03T06:56:27.665+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-033","review_status":"approved","bound_author_id":987332001},"before_row":null},{"key":{"edition_id":987232001},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987132001,"evidence":[{"note":"Exact Dutch paperback9789060195529/KBp801595169,p802527558,p802539505 trans